//! Pinned WPT MIME type parsing and `Content-Type` extraction cases.
//!
//! The data is generated by `tools/import_wpt_mime_tests.py`; every record
//! of the three upstream files is checked, with no expected failures.

use rustic_net::Headers;
use rustic_net::mime::{MimeType, extract_mime_type, legacy_extract_encoding};

// Kept out of rustfmt's reach: the generator owns this file's layout.
include!("fixtures/mime_cases.rs");

#[test]
fn mimesniff_mime_types() {
    let mut failures = Vec::new();
    for &(input, output, encoding) in MIME_TYPES {
        let parsed = MimeType::parse(input);
        let serialized = parsed.as_ref().map(ToString::to_string);
        if serialized.as_deref() != output {
            failures.push(format!("{input:?}: got {serialized:?}, want {output:?}"));
        }
        let charset = parsed
            .as_ref()
            .and_then(MimeType::charset)
            .map(|e| e.name());
        if parsed.is_some() && charset != encoding {
            failures.push(format!(
                "{input:?}: encoding {charset:?}, want {encoding:?}"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {}:\n{}",
        failures.len(),
        MIME_TYPES.len(),
        failures.join("\n")
    );
}

#[test]
fn mimesniff_generated_mime_types() {
    let failures: Vec<String> = GENERATED_MIME_TYPES
        .iter()
        .filter_map(|&(input, output)| {
            let got = MimeType::parse(input).map(|mime| mime.to_string());
            (got.as_deref() != output).then(|| format!("{input:?}: got {got:?}, want {output:?}"))
        })
        .collect();
    assert!(
        failures.is_empty(),
        "{} of {}:\n{}",
        failures.len(),
        GENERATED_MIME_TYPES.len(),
        failures.join("\n")
    );
}

#[test]
fn fetch_content_type_extraction() {
    let mut failures = Vec::new();
    for &(lines, encoding, mime_type) in CONTENT_TYPES {
        // Each entry is one `Content-Type` header line, as WPT's server sends.
        let mut headers = Headers::new();
        for line in lines {
            headers.append("Content-Type", line.as_bytes()).unwrap();
        }
        let extracted = extract_mime_type(&headers);
        let serialized = extracted.as_ref().map(ToString::to_string);
        if serialized.as_deref() != mime_type {
            failures.push(format!("{lines:?}: got {serialized:?}, want {mime_type:?}"));
        }
        let got = legacy_extract_encoding(extracted.as_ref()).map(|e| e.name());
        if got != encoding {
            failures.push(format!("{lines:?}: encoding {got:?}, want {encoding:?}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {}:\n{}",
        failures.len(),
        CONTENT_TYPES.len(),
        failures.join("\n")
    );
}
